import React, {useMemo, useRef, useState} from "react";
import {
    Accordion,
    AccordionDetails,
    AccordionSummary,
    Alert,
    Button,
    Chip,
    LinearProgress,
} from "@mui/material";
import {GridColDef, GridToolbar} from "@mui/x-data-grid";
import UploadFileOutlinedIcon from "@mui/icons-material/UploadFileOutlined";
import ExpandMoreOutlinedIcon from "@mui/icons-material/ExpandMoreOutlined";
import ArrowForwardOutlinedIcon from "@mui/icons-material/ArrowForwardOutlined";
import SaveOutlinedIcon from "@mui/icons-material/SaveOutlined";
import styledCom from "styled-components";
import {toast} from "react-toastify";
import {Link, useLocation, useNavigate} from "react-router-dom";
import {CategoryType} from "../../models/category";
import {ProductFileColumn, ProductFileColumnMapping, ProductFileGtinRow, ProductFileSelectionLocationState} from "../../models/productFileImport";
import {getApiErrorMessage} from "../../api/errors";
import {useTranslation} from "../../i18n";
import {useAuth} from "../../auth/AuthContext";
import {MainDiv, PageHeader, PageSubtitle, PageTitle, PageTitleGroup, StyledDataGrid, Surface} from "../../ui/commonStyled/commonStyled";
import ProductLifecycleLink from './lifecycle/ProductLifecycleLink';
import CoreButton from "../../ui/buttons/coreButton";
import TableChartOutlinedIcon from "@mui/icons-material/TableChartOutlined";
import ProductFileColumnDialog from "./ProductFileColumnDialog";
import {useGetLastLevelCategoriesQuery} from "../categories/categoriesApi";
import {
    useAnalyzeProductFileMutation,
    useGetProductFileImportSettingsQuery,
    usePreviewProductFileMutation,
    useUpdateProductFileImportSettingsMutation,
} from "../products/productsApi";
import CatalogGenerationTabs from "./CatalogGenerationTabs";

const UploadCard = styledCom(Surface)({display: "grid", placeItems: "center", gap: "14px", minHeight: "300px", maxWidth: "760px", margin: "0 auto", textAlign: "center"});
const DropButton = styledCom.button<{ $dragging: boolean }>(({ $dragging }) => ({
    display: "grid", placeItems: "center", gap: "10px", width: "100%", minHeight: "210px", padding: "28px", cursor: "pointer",
    color: $dragging ? "var(--color-primary)" : "var(--color-text)", background: $dragging ? "var(--color-primary-soft)" : "var(--gradient-subtle)",
    border: `2px dashed ${$dragging ? "var(--color-primary)" : "var(--color-border-strong)"}`, borderRadius: "16px",
}));
const HiddenInput = styledCom.input({position: "absolute", width: 1, height: 1, overflow: "hidden", clip: "rect(0,0,0,0)"});
const UploadIcon = styledCom.div({display: "grid", placeItems: "center", width: 58, height: 58, color: "var(--color-primary)", background: "var(--color-primary-soft)", borderRadius: 16});
const Muted = styledCom.span({color: "var(--color-muted)", fontSize: 13});
const Steps = styledCom.div({display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 8, marginBottom: 16});
const Step = styledCom.div<{ $active?: boolean }>(({ $active }) => ({padding: "10px 12px", color: $active ? "var(--color-primary)" : "var(--color-muted)", fontSize: 13, fontWeight: 750, textAlign: "center", background: $active ? "var(--color-primary-soft)" : "var(--color-surface-soft)", border: `1px solid ${$active ? "var(--color-primary-border)" : "var(--color-border)"}`, borderRadius: 10}));
const Workspace = styledCom(Surface)({display: "grid", gap: 16});
const FileBar = styledCom.div({display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12, flexWrap: "wrap"});
const FileInfo = styledCom.div({display: "grid", gap: 3, strong: {fontSize: 16}, small: {color: "var(--color-muted)"}});
const MappingGrid = styledCom.div({display: "grid", gridTemplateColumns: "repeat(2, minmax(0, 1fr))", gap: 10, "@media (max-width: 760px)": {gridTemplateColumns: "1fr"}});
const SelectionSummary = styledCom.div({display: "flex", gap: 7, flexWrap: "wrap", minHeight: 32, alignItems: "center"});
const MappingCard = styledCom.div({display: "grid", gap: 5, padding: "16px", background: "var(--color-surface-soft)", border: "1px solid var(--color-border)", borderRadius: 14, minWidth: 0,
    strong: {overflowWrap: "anywhere"}});
const Footer = styledCom.div({display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, flexWrap: "wrap", paddingTop: 4});

const ProductFileGenerationPage = () => {
    const {t} = useTranslation();
    const {isCompanyAdmin} = useAuth();
    const navigate = useNavigate();
    const location = useLocation();
    const restored = location.state as ProductFileSelectionLocationState | null;
    const inputRef = useRef<HTMLInputElement>(null);
    const [file, setFile] = useState<File | null>(restored?.file ?? null);
    const [dragging, setDragging] = useState(false);
    const [categoryId, setCategoryId] = useState(restored?.categoryId ?? "");
    const [nameColumnKey, setNameColumnKey] = useState(restored?.nameColumnKey ?? "");
    const [countColumnKey, setCountColumnKey] = useState(restored?.analysis?.isEpassDocument ? "" : restored?.countColumnKey ?? "");
    const [selectedKeys, setSelectedKeys] = useState<Set<string>>(new Set(restored?.selectedColumnKeys ?? []));
    const [restoredAnalysis, setRestoredAnalysis] = useState(restored?.analysis ?? null);
    const [mappingOpen, setMappingOpen] = useState(Boolean(restored?.analysis));
    const [analyzeFile, analysis] = useAnalyzeProductFileMutation();
    const [previewFile, preview] = usePreviewProductFileMutation();
    const [saveSettings, settingsSave] = useUpdateProductFileImportSettingsMutation();
    const {data: settings} = useGetProductFileImportSettingsQuery();
    const {data: categories = [], isLoading: categoriesLoading, isError: categoriesFailed, refetch: refetchCategories} = useGetLastLevelCategoriesQuery({type: CategoryType.Product});
    const analysisData = analysis.data ?? restoredAnalysis;

    const selectableColumns = useMemo(() => analysisData?.columns.filter((column) => column.isSelectable) ?? [], [analysisData]);
    const fieldColumns = useMemo(() => selectableColumns.filter((column) =>
            column.semanticRole !== "Gtin" &&
            column.sourceKey !== nameColumnKey &&
            column.sourceKey !== countColumnKey),
        [countColumnKey, nameColumnKey, selectableColumns]);
    const selectedColumns = useMemo(() => fieldColumns.filter((column) => selectedKeys.has(column.sourceKey)), [fieldColumns, selectedKeys]);
    const mapping = useMemo<ProductFileColumnMapping>(() => ({categoryId, nameColumnKey, priceColumnKey: "", countColumnKey,
        selectedColumnKeys: selectedColumns.map(column => column.sourceKey)}), [categoryId, nameColumnKey, countColumnKey, selectedColumns]);
    const gtinColumns = useMemo<GridColDef<ProductFileGtinRow>[]>(() => [
        {field: "sourceRowNumber", headerName: t("Excel row"), width: 105, type: "number"},
        {field: "gtinRaw", headerName: t("GTIN from file"), minWidth: 180, flex: 1},
        {field: "gtinNormalized", headerName: t("Normalized GTIN"), minWidth: 190, flex: 1},
        {field: "validationErrors", headerName: t("Validation"), minWidth: 230, flex: 1, valueGetter: ({row}) => row.validationErrors.join(" ") || t("Valid")},
    ], [t]);
    const gtinRows = (analysisData?.parsedGtins ?? []).map((row) => ({...row, id: `${row.sourceRowNumber}-${row.gtinNormalized}`}));

    const reset = () => {
        setFile(null); setRestoredAnalysis(null); analysis.reset(); preview.reset(); setCategoryId(""); setNameColumnKey(""); setCountColumnKey(""); setSelectedKeys(new Set()); setMappingOpen(false);
        if (inputRef.current) inputRef.current.value = "";
    };
    const analyze = async (nextFile: File) => {
        if (!/\.xlsx?$/i.test(nextFile.name) || nextFile.size === 0 || nextFile.size > 50 * 1024 * 1024) {toast.error("Выберите непустой файл XLS или XLSX размером до 50 МБ."); return;}
        setFile(nextFile); setRestoredAnalysis(null); analysis.reset(); preview.reset();
        const body = new FormData(); body.append("file", nextFile);
        try {
            const response = await analyzeFile(body).unwrap();
            setRestoredAnalysis(response);
            setNameColumnKey(response.suggestedNameColumnKey);
            setCountColumnKey(response.isEpassDocument ? "" : response.suggestedCountColumnKey);
            setSelectedKeys(new Set(response.columns.filter((column) => column.isSelectedByDefault && column.semanticRole !== "Gtin" && column.sourceKey !== response.suggestedNameColumnKey && column.sourceKey !== response.suggestedPriceColumnKey && column.sourceKey !== response.suggestedCountColumnKey).map((column) => column.sourceKey)));
            setMappingOpen(true);
        } catch (error) { toast.error(getApiErrorMessage(error, t("The file could not be analyzed."))); }
    };
    const toggleField = (column: ProductFileColumn) => setSelectedKeys((current) => {const next = new Set(current); next.has(column.sourceKey) ? next.delete(column.sourceKey) : next.add(column.sourceKey); return next;});
    const applyMapping = (next: ProductFileColumnMapping) => {
        setCategoryId(next.categoryId); setNameColumnKey(next.nameColumnKey);
        setCountColumnKey(analysisData?.isEpassDocument ? "" : next.countColumnKey); setSelectedKeys(new Set(next.selectedColumnKeys));
    };
    const saveCompanyDefaults = async () => {
        const byKey = new Map(selectableColumns.map((column) => [column.sourceKey, column]));
        try {
            await saveSettings({
                nameColumnName: byKey.get(nameColumnKey)?.displayName ?? "",
                priceColumnName: "",
                countColumnName: analysisData?.isEpassDocument ? "" : byKey.get(countColumnKey)?.displayName ?? "",
                selectedColumnNames: selectedColumns.map((column) => column.displayName),
                additionalFields: settings?.additionalFields ?? {},
            }).unwrap();
            toast.success(t("Company import defaults saved"));
        } catch (error) { toast.error(getApiErrorMessage(error, t("Company import defaults could not be saved"))); }
    };
    const openReview = async (next = mapping) => {
        if (!file || !analysisData || !categories.some(category => String(category.id) === next.categoryId) || !next.nameColumnKey) { toast.error(t("Select a category and product name column.")); return; }
        if (analysisData.detectedProductRowCount === 0) {toast.error("В файле нет товаров с корректным GTIN. Проверьте файл или выберите другой."); return;}
        const cleanCountKey = analysisData.isEpassDocument ? "" : next.countColumnKey;
        const cleanSelectedKeys = analysisData.columns.filter(column => column.isSelectable && column.semanticRole !== "Gtin" &&
            next.selectedColumnKeys.includes(column.sourceKey) && ![next.nameColumnKey, cleanCountKey].includes(column.sourceKey)).map(column => column.sourceKey);
        const body = new FormData(); body.append("file", file); body.append("nameColumnKey", next.nameColumnKey); body.append("priceColumnKey", ""); body.append("countColumnKey", cleanCountKey); cleanSelectedKeys.forEach((key) => body.append("selectedColumnKeys", key));
        try {
            const response = await previewFile(body).unwrap();
            setMappingOpen(false);
            navigate("/catalogGeneration/file/review", {replace: true, state: {file, categoryId: next.categoryId, nameColumnKey: next.nameColumnKey, priceColumnKey: "", countColumnKey: cleanCountKey, selectedColumnKeys: cleanSelectedKeys, defaultAdditionalFields: settings?.additionalFields ?? analysisData.configuredAdditionalFields ?? {}, analysis: analysisData, preview: response, reviewDraft: restored?.reviewDraft?.mapping === JSON.stringify([next.categoryId, next.nameColumnKey, "", cleanCountKey, cleanSelectedKeys]) ? restored.reviewDraft : undefined}});
        } catch (error) { toast.error(getApiErrorMessage(error, t("The product preview could not be prepared."))); }
    };
    const busy = analysis.isLoading || preview.isLoading;

    return <MainDiv>
        <ProductLifecycleLink step={6}/>
        <PageHeader><PageTitleGroup><PageTitle>{t("Генерация из файла ePass")}</PageTitle><PageSubtitle>{"Загрузите Excel из ePass, выберите назначение колонок и проверьте карточки. Остатки существующих товаров сохраняются по умолчанию."}</PageSubtitle></PageTitleGroup></PageHeader>
        <CatalogGenerationTabs/>
        <Steps><Step $active={!analysisData}>1. {t("File")}</Step><Step $active={Boolean(analysisData)}>2. {t("Column mapping")}</Step><Step>3. {t("Product review")}</Step></Steps>
        {!analysisData ? <UploadCard>
            <DropButton type="button" $dragging={dragging} disabled={busy} onClick={() => inputRef.current?.click()} onDragOver={(event: React.DragEvent<HTMLButtonElement>) => {event.preventDefault(); setDragging(true);}} onDragLeave={() => setDragging(false)} onDrop={(event: React.DragEvent<HTMLButtonElement>) => {event.preventDefault(); setDragging(false); const next = event.dataTransfer.files.item(0); if (next) void analyze(next);}}>
                <UploadIcon><UploadFileOutlinedIcon fontSize="large"/></UploadIcon><strong>{analysis.isLoading && file ? file.name : t("Choose or drag an Excel file")}</strong><Muted>{analysis.isLoading ? t("Analyzing file...") : t("XLS or XLSX up to 50 MB. Analysis starts immediately.")}</Muted>
            </DropButton>
            <HiddenInput ref={inputRef} type="file" accept=".xls,.xlsx" aria-label={t("Choose or drag an Excel file")} disabled={busy} onChange={(event: React.ChangeEvent<HTMLInputElement>) => {const next = event.target.files?.item(0); if (next) void analyze(next);}}/>
            {analysis.isLoading && <LinearProgress sx={{width: "100%"}}/>}<Muted>{t("The document is processed in memory and is not stored.")}</Muted>
        </UploadCard> : <Workspace>
            <FileBar><FileInfo><strong>{analysisData.fileName}</strong><small>{analysisData.sheetName} · {analysisData.detectedProductRowCount} {t("products")} · {analysisData.sourceColumnCount} {t("columns")}</small></FileInfo><CoreButton muiType="secondary" disabled={busy} text={t("Replace file")} onClick={reset}/></FileBar>
            {analysisData.hasSavedSettings && <Alert severity="success">{t("Company settings applied")}: {analysisData.appliedSettingColumnCount}</Alert>}
            {analysisData.warnings.length > 0 && <Alert severity="warning">{analysisData.warnings.slice(0, 4).join(" ")}</Alert>}
            <FileBar><FileInfo><strong>{t("Column mapping")}</strong><Muted>{t("Click column headers to choose what goes into the product card.")}</Muted></FileInfo>
                <CoreButton leftIcon={<TableChartOutlinedIcon/>} disabled={busy} text={t("Configure columns")} onClick={() => {preview.reset(); setMappingOpen(true);}}/></FileBar>
            {analysisData.isEpassDocument && <Alert severity="info">Распознан ePass. «Количество товара» — содержимое упаковки, например 130 граммов. Новые карточки создаются с остатком 0; остатки задаются при оформлении прихода.</Alert>}
            <MappingGrid>
                <MappingCard><Muted>{t("Product category")}</Muted><strong>{categories.find(category => String(category.id) === categoryId)?.name ?? t("Not selected")}</strong></MappingCard>
                <MappingCard><Muted>{t("Product name")}</Muted><strong>{selectableColumns.find(column => column.sourceKey === nameColumnKey)?.displayName ?? t("Not selected")}</strong></MappingCard>
                <MappingCard><Muted>{analysisData.isEpassDocument ? t("Stock quantity") : t("Stock column")}</Muted><strong>{analysisData.isEpassDocument ? t("Set stock through a warehouse receipt.") : selectableColumns.find(column => column.sourceKey === countColumnKey)?.displayName ?? t("Do not import from file")}</strong></MappingCard>
            </MappingGrid>
            {(!categories.some(category => String(category.id) === categoryId) || !nameColumnKey) && <Alert severity="warning" action={<button type="button" onClick={() => setMappingOpen(true)}>Выбрать</button>}>Чтобы проверить товары, выберите категорию и колонку с названием в настройках колонок.</Alert>}
            <div><Muted>{t("Fields added to each product")}</Muted><SelectionSummary>{selectedColumns.length === 0 ? <Muted>{t("No additional document fields selected")}</Muted> : selectedColumns.map((column) => <Chip key={column.sourceKey} size="small" label={column.displayName} onDelete={() => toggleField(column)}/>)}</SelectionSummary></div>
            <Accordion disableGutters><AccordionSummary expandIcon={<ExpandMoreOutlinedIcon/>}><strong>GTIN ({gtinRows.length})</strong></AccordionSummary><AccordionDetails><StyledDataGrid autoHeight rows={gtinRows} columns={gtinColumns} slots={{toolbar: GridToolbar}} slotProps={{toolbar: {showQuickFilter: true}}} pageSizeOptions={[25, 50, 100]} initialState={{pagination: {paginationModel: {pageSize: 25, page: 0}}}} disableRowSelectionOnClick/></AccordionDetails></Accordion>
            {preview.isLoading && <LinearProgress/>}
            <Footer>{isCompanyAdmin ? <CoreButton muiType="secondary" leftIcon={<SaveOutlinedIcon/>} disabled={settingsSave.isLoading} text={settingsSave.isLoading ? t("Saving...") : t("Save as company default")} onClick={() => void saveCompanyDefaults()}/> : <span/>}<CoreButton muiType="success" rightIcon={<ArrowForwardOutlinedIcon/>} disabled={busy || !categories.some(category => String(category.id) === categoryId) || !nameColumnKey || analysisData.detectedProductRowCount === 0} text={preview.isLoading ? t("Preparing preview...") : t("Check products")} onClick={() => void openReview()}/></Footer>
            <ProductFileColumnDialog open={mappingOpen} analysis={analysisData} mapping={mapping} categories={categories} busy={Boolean(busy)}
                categoryNotice={categoriesLoading ? <Alert severity="info">Загружаем категории…</Alert> : categoriesFailed ? <Alert severity="error">Категории не загрузились.<Button onClick={() => void refetchCategories()}>Повторить</Button></Alert> : !categories.length ? <Alert severity="warning">Для сохранения нужна категория товаров.<Button component={Link} to="/productCategories" target="_blank" rel="noopener noreferrer">Открыть категории</Button><Button onClick={() => void refetchCategories()}>Обновить категории</Button></Alert> : undefined}
                error={preview.isError ? getApiErrorMessage(preview.error, t("The product preview could not be prepared.")) : undefined}
                onClose={() => setMappingOpen(false)} onSave={next => {applyMapping(next); setMappingOpen(false);}}
                onContinue={next => {applyMapping(next); void openReview(next);}}/>
        </Workspace>}
    </MainDiv>;
};

export default ProductFileGenerationPage;
