import React, {useEffect, useMemo, useState} from "react";
import {Alert, Autocomplete, Box, Button, Chip, CircularProgress, Dialog, DialogActions, DialogContent,
    DialogTitle, FormControlLabel, IconButton, InputAdornment, Switch, Table, TableBody, TableCell,
    TableContainer, TableHead, TableRow, TextField, Tooltip, Typography, useMediaQuery, useTheme} from "@mui/material";
import CloseOutlinedIcon from "@mui/icons-material/CloseOutlined";
import TableChartOutlinedIcon from "@mui/icons-material/TableChartOutlined";
import CheckBoxOutlinedIcon from "@mui/icons-material/CheckBoxOutlined";
import CheckBoxOutlineBlankOutlinedIcon from "@mui/icons-material/CheckBoxOutlineBlankOutlined";
import LockOutlinedIcon from "@mui/icons-material/LockOutlined";
import SearchOutlinedIcon from "@mui/icons-material/SearchOutlined";
import ArrowForwardOutlinedIcon from "@mui/icons-material/ArrowForwardOutlined";
import {ProductFileAnalysis, ProductFileColumn, ProductFileColumnMapping} from "../../models/productFileImport";
import {useTranslation} from "../../i18n";

type ColumnRole = "name" | "count" | "fields";
type CategoryOption = {id: string | number; name: string};
type Props = {
    open: boolean;
    analysis: ProductFileAnalysis;
    mapping: ProductFileColumnMapping;
    categories: CategoryOption[];
    busy?: boolean;
    error?: string;
    categoryNotice?: React.ReactNode;
    onClose: () => void;
    onSave: (mapping: ProductFileColumnMapping) => void;
    onContinue: (mapping: ProductFileColumnMapping) => void;
};

const ProductFileColumnDialog = ({open, analysis, mapping, categories, busy = false, error, categoryNotice, onClose, onSave, onContinue}: Props) => {
    const {t} = useTranslation();
    const theme = useTheme();
    const mobile = useMediaQuery(theme.breakpoints.down("md"));
    const [draft, setDraft] = useState(mapping);
    const [activeRole, setActiveRole] = useState<ColumnRole>("fields");
    const [query, setQuery] = useState("");
    const [showEmpty, setShowEmpty] = useState(false);
    const [showTechnical, setShowTechnical] = useState(false);
    const [selectedOnly, setSelectedOnly] = useState(false);

    useEffect(() => {
        if (open) {
            setDraft({...mapping, priceColumnKey: "", countColumnKey: analysis.isEpassDocument ? "" : mapping.countColumnKey,
                selectedColumnKeys: [...mapping.selectedColumnKeys]});
            setActiveRole(mapping.nameColumnKey ? "fields" : "name");
            setQuery(""); setShowEmpty(false); setShowTechnical(false); setSelectedOnly(false);
        }
    }, [open, mapping, analysis.isEpassDocument]);

    const byKey = useMemo(() => new Map(analysis.columns.map(column => [column.sourceKey, column])), [analysis.columns]);
    const selectedKeys = useMemo(() => new Set(draft.selectedColumnKeys), [draft.selectedColumnKeys]);
    const roleFor = (column: ProductFileColumn) => column.semanticRole === "Gtin" ? "gtin" :
        column.sourceKey === draft.nameColumnKey ? "name" :
            column.sourceKey === draft.countColumnKey ? "count" : selectedKeys.has(column.sourceKey) ? "fields" : null;
    const roleLabel = (role: string) => role === "gtin" ? "GTIN" : role === "name" ? t("Product name") :
        role === "count" ? t("Stock quantity") : t("Additional product fields");
    const visibleColumns = [...analysis.columns].sort((a, b) => a.ordinal - b.ordinal).filter(column => {
        const role = roleFor(column);
        if (role && role !== "fields") return true;
        if (selectedOnly && !role) return false;
        if (!role && !showEmpty && !column.sampleValues.some(value => value.trim())) return false;
        if (!role && !showTechnical && column.isTechnical && column.semanticRole !== "FullNameCandidate") return false;
        const search = query.trim().toLocaleLowerCase();
        return !search || `${column.displayName} ${column.rawHeader ?? ""} ${column.excelColumnName} ${column.sampleValues.join(" ")}`.toLocaleLowerCase().includes(search);
    });
    const selectableFields = visibleColumns.filter(column => column.isSelectable && !column.isLocked &&
        column.semanticRole !== "Gtin" && ![draft.nameColumnKey, draft.countColumnKey].includes(column.sourceKey));
    const normalizedMapping = (): ProductFileColumnMapping => ({...draft, priceColumnKey: "",
        countColumnKey: analysis.isEpassDocument ? "" : draft.countColumnKey,
        selectedColumnKeys: analysis.columns.filter(column => column.isSelectable && column.semanticRole !== "Gtin" &&
            selectedKeys.has(column.sourceKey) && ![draft.nameColumnKey, draft.countColumnKey].includes(column.sourceKey))
            .map(column => column.sourceKey)});
    const selectedCount = normalizedMapping().selectedColumnKeys.length;
    const validCategory = categories.some(category => String(category.id) === draft.categoryId);
    const canContinue = validCategory && Boolean(draft.nameColumnKey && byKey.get(draft.nameColumnKey)?.isSelectable) && analysis.detectedProductRowCount > 0;

    const chooseColumn = (column: ProductFileColumn) => {
        if (busy || !column.isSelectable || column.isLocked || column.semanticRole === "Gtin") return;
        const currentRole = roleFor(column);
        if (currentRole && currentRole !== "fields" && currentRole !== activeRole) return;
        if (activeRole === "fields") {
            setDraft(current => ({...current, selectedColumnKeys: selectedKeys.has(column.sourceKey)
                ? current.selectedColumnKeys.filter(key => key !== column.sourceKey) : [...current.selectedColumnKeys, column.sourceKey]}));
        } else {
            const key = activeRole === "name" ? "nameColumnKey" : "countColumnKey";
            setDraft(current => ({...current, [key]: column.sourceKey,
                selectedColumnKeys: current.selectedColumnKeys.filter(value => value !== column.sourceKey)}));
            setActiveRole("fields");
        }
    };
    const clearRole = (role: ColumnRole) => {
        const key = role === "name" ? "nameColumnKey" : "countColumnKey";
        setDraft(current => ({...current, [key]: ""}));
        if (role === "name") setActiveRole("name");
    };
    const rows = analysis.previewRows ?? [];
    const rowNumberSx = {position: "sticky", left: 0, zIndex: 3, width: 44, minWidth: 44, maxWidth: 44,
        p: 1, textAlign: "center" as const, fontSize: 12, color: "text.secondary", bgcolor: "background.default", borderRight: "1px solid", borderRightColor: "divider"};

    return <Dialog open={open} fullScreen={mobile} maxWidth={false} onClose={() => !busy && onClose()}
        aria-labelledby="product-file-columns-title" PaperProps={{sx: {width: mobile ? "100%" : "min(1480px, calc(100vw - 48px))",
            height: mobile ? "100%" : "min(860px, calc(100dvh - 48px))", m: mobile ? 0 : 3, borderRadius: mobile ? 0 : 5, overflow: "hidden"}}}>
        <DialogTitle component="div" id="product-file-columns-header" sx={{display: "flex", alignItems: "center", gap: 1.5, pb: 1.5}}>
            <Box sx={{display: "grid", placeItems: "center", width: 46, height: 46, borderRadius: 3, bgcolor: "primary.light", color: "primary.contrastText", flexShrink: 0}}><TableChartOutlinedIcon/></Box>
            <Box sx={{flex: 1, minWidth: 0}}><Typography id="product-file-columns-title" component="h2" variant="h6" fontWeight={750}>{t("Choose columns from the file")}</Typography>
                <Typography variant="body2" color="text.secondary" noWrap>{analysis.fileName} · {analysis.sheetName} · {analysis.detectedProductRowCount} {t("products")}</Typography></Box>
            <IconButton aria-label={t("Close column selection")} disabled={busy} onClick={onClose}><CloseOutlinedIcon/></IconButton>
        </DialogTitle>
        <DialogContent sx={{p: {xs: 2, md: 3}, pt: "8px !important", display: "flex", flexDirection: "column", minHeight: 0}}>
            {error && <Alert severity="error" sx={{mb: 1.5}}>{error}</Alert>}
            <Box sx={{display: "grid", gridTemplateColumns: {xs: "minmax(0, 1fr)", md: "270px minmax(0, 1fr)"}, gap: 2.5, flex: {xs: "none", md: 1}, minHeight: 0}}>
                <Box sx={{display: "flex", flexDirection: "column", minWidth: 0, gap: 1.5, overflowY: {md: "auto"}, pr: {md: 0.5}}}>
                    <Typography variant="overline" color="text.secondary" sx={{display: {xs: "none", md: "block"}}}>1. {t("Where to save products")}</Typography>
                    <Autocomplete options={categories} disabled={busy} value={categories.find(category => String(category.id) === draft.categoryId) ?? null}
                        isOptionEqualToValue={(option, value) => String(option.id) === String(value.id)} getOptionLabel={option => option.name}
                        onChange={(_, category) => setDraft(current => ({...current, categoryId: category ? String(category.id) : ""}))}
                        renderInput={params => <TextField {...params} label={t("Product category")} required placeholder={t("Select a product category")}/>}/>
                    {categoryNotice}
                    <Typography variant="overline" color="text.secondary" sx={{mt: 0.5, display: {xs: "none", md: "block"}}}>2. {t("Column mapping")}</Typography>
                    <Box sx={{display: {xs: "flex", md: "contents"}, gap: 1, overflowX: {xs: "auto", md: "visible"}, flexShrink: 0, pb: {xs: 0.5, md: 0}}}>
                    {(["name", ...(!analysis.isEpassDocument ? ["count"] : [])] as ColumnRole[]).map(role => {
                        const key = role === "name" ? draft.nameColumnKey : draft.countColumnKey;
                        const column = byKey.get(key);
                        const active = activeRole === role;
                        return <Box key={role} sx={{display: "flex", alignItems: "center", border: "1px solid", borderColor: active ? "primary.main" : "divider",
                            borderRadius: 2.5, bgcolor: active ? "action.selected" : "background.paper", overflow: "hidden", minWidth: {xs: 170, md: 0}, flexShrink: 0}}>
                            <Button disabled={busy} aria-pressed={active} onClick={() => setActiveRole(role)} sx={{flex: 1, p: 1.5, display: "block", textAlign: "left", textTransform: "none", minWidth: 0, color: "text.primary"}}>
                                <Typography fontSize={13} fontWeight={750}>{roleLabel(role)}{role === "name" ? " *" : ""}</Typography>
                                <Typography fontSize={12} color={active ? "primary.main" : "text.secondary"} sx={{mt: 0.5, overflowWrap: "anywhere"}}>
                                    {active ? t("Choose in table") : column ? `${column.excelColumnName} · ${column.displayName}` : role === "name" ? t("Not selected") : t("Do not import from file")}</Typography>
                            </Button>
                            {key && <IconButton size="small" disabled={busy} aria-label={t("Remove column mapping", {role: roleLabel(role)})} onClick={() => clearRole(role)} sx={{mr: 0.5}}><CloseOutlinedIcon fontSize="small"/></IconButton>}
                        </Box>;
                    })}
                    <Button variant={activeRole === "fields" ? "contained" : "outlined"} disabled={busy} aria-pressed={activeRole === "fields"}
                        onClick={() => setActiveRole("fields")} sx={{justifyContent: "flex-start", textTransform: "none", borderRadius: 2.5, p: 1.5, minWidth: {xs: 195, md: 0}, flexShrink: 0}}>
                        <Box><Typography fontSize={13} fontWeight={750}>{t("Additional product fields")}</Typography><Typography fontSize={12} sx={{mt: 0.5, opacity: 0.85}}>{t("Selected characteristics: {count}", {count: selectedCount})}</Typography></Box>
                    </Button>
                    </Box>
                    <Typography variant="body2" color="text.secondary" sx={{fontSize: {xs: 12, md: 14}}}>{t("Click column headers to choose what goes into the product card.")}</Typography>
                    {analysis.isEpassDocument && <Alert severity="info" icon={false} sx={{borderRadius: 2.5, fontSize: 12}}>{t("New ePass products start with zero stock. Packaging quantity stays a characteristic.")}</Alert>}
                </Box>
                <Box sx={{display: "flex", flexDirection: "column", minWidth: 0, minHeight: {xs: 350, md: 0}, border: "1px solid", borderColor: "divider", borderRadius: 3, overflow: "hidden", bgcolor: "background.default"}}>
                    <Box sx={{px: 2, py: 1.5, bgcolor: "background.paper", borderBottom: "1px solid", borderBottomColor: "divider"}}>
                        <Box sx={{display: "flex", alignItems: "center", justifyContent: "space-between", gap: 1, mb: 1.25}}>
                            <Typography fontWeight={750}>{t("File preview")}</Typography><Chip size="small" color="primary" variant="outlined" label={roleLabel(activeRole)}/>
                        </Box>
                        <TextField size="small" fullWidth label={t("Search by column name or value")} value={query} disabled={busy}
                            onChange={event => setQuery(event.target.value)} InputProps={{startAdornment: <InputAdornment position="start"><SearchOutlinedIcon fontSize="small"/></InputAdornment>}}/>
                        <Box sx={{display: "flex", alignItems: "center", flexWrap: "wrap", columnGap: 1}}>
                            <FormControlLabel control={<Switch size="small" checked={showEmpty} disabled={busy} onChange={event => setShowEmpty(event.target.checked)}/>} label={<Typography fontSize={12}>{t("Show empty columns")}</Typography>}/>
                            <FormControlLabel control={<Switch size="small" checked={showTechnical} disabled={busy} onChange={event => setShowTechnical(event.target.checked)}/>} label={<Typography fontSize={12}>{t("Show technical columns")}</Typography>}/>
                            <FormControlLabel control={<Switch size="small" checked={selectedOnly} disabled={busy} onChange={event => setSelectedOnly(event.target.checked)}/>} label={<Typography fontSize={12}>{t("Only selected columns")}</Typography>}/>
                        </Box>
                        <Box sx={{display: "flex", alignItems: "center", gap: 1, flexWrap: "wrap"}}>
                            <Button size="small" disabled={busy || selectableFields.length === 0} onClick={() => setDraft(current => ({...current,
                                selectedColumnKeys: Array.from(new Set([...current.selectedColumnKeys, ...selectableFields.map(column => column.sourceKey)]))}))}>{t("Select visible fields")}</Button>
                            <Button size="small" color="inherit" disabled={busy || selectedCount === 0} onClick={() => setDraft(current => ({...current, selectedColumnKeys: []}))}>{t("Clear characteristics")}</Button>
                            <Typography fontSize={11} color="text.secondary" sx={{ml: "auto"}}>{visibleColumns.length} / {analysis.sourceColumnCount} {t("columns")}</Typography>
                        </Box>
                    </Box>
                    <TableContainer sx={{flex: {xs: "none", md: 1}, height: {xs: 300, md: "auto"}, minHeight: 0, overflow: "auto"}} tabIndex={0} aria-label={t("File preview")}>
                        <Table size="small" sx={{width: "max-content", minWidth: "100%", tableLayout: "fixed"}} aria-label={t("File preview")}>
                            <TableHead>
                                <TableRow><TableCell sx={{...rowNumberSx, top: 0, zIndex: 6, height: 34, p: 0}}>#</TableCell>
                                    {visibleColumns.map(column => <TableCell key={column.sourceKey} align="center" sx={{position: "sticky", top: 0, zIndex: 4, height: 34, p: 0,
                                        width: 210, minWidth: 210, maxWidth: 210, fontSize: 12, fontWeight: 750, bgcolor: "background.default", borderRight: "1px solid", borderRightColor: "divider"}}>{column.excelColumnName}</TableCell>)}
                                </TableRow>
                                <TableRow><TableCell sx={{...rowNumberSx, top: 34, zIndex: 6}}>{analysis.headerRowNumber}</TableCell>
                                    {visibleColumns.map(column => {
                                        const role = roleFor(column);
                                        const locked = column.isLocked || column.semanticRole === "Gtin" || !column.isSelectable;
                                        const conflict = Boolean(role && role !== "fields" && role !== activeRole);
                                        const disabled = busy || locked || conflict;
                                        const label = activeRole === "fields" ? t("Select field {column}", {column: column.displayName}) : t("Choose column {column} for {role}", {column: column.displayName, role: roleLabel(activeRole)});
                                        const hint = column.semanticRole === "Gtin" ? t("GTIN is recognized automatically") : conflict ? t("Column is already used for {role}", {role: roleLabel(role!)}) : column.rawHeader ?? column.displayName;
                                        return <TableCell key={column.sourceKey} sx={{position: "sticky", top: 34, zIndex: 4, p: 0, width: 210, minWidth: 210, maxWidth: 210,
                                            bgcolor: role ? "action.selected" : "background.paper", borderRight: "1px solid", borderRightColor: "divider", verticalAlign: "top"}}>
                                            <Tooltip title={hint} arrow><span><Button disabled={disabled} aria-label={label} aria-pressed={Boolean(role)} onClick={() => chooseColumn(column)}
                                                sx={{width: "100%", minHeight: 130, p: 1.5, display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 1,
                                                    textTransform: "none", textAlign: "left", color: "text.primary", borderRadius: 0, "&.Mui-disabled": {color: "text.secondary"}}}>
                                                <Box sx={{display: "flex", alignItems: "center", gap: 0.75, width: "100%"}}>
                                                    {locked ? <LockOutlinedIcon fontSize="small"/> : role ? <CheckBoxOutlinedIcon fontSize="small" color="primary"/> : <CheckBoxOutlineBlankOutlinedIcon fontSize="small"/>}
                                                    <Typography fontSize={10} fontWeight={700} color={role ? "primary.main" : "text.secondary"}>{role ? roleLabel(role) : t("Not imported")}</Typography>
                                                </Box>
                                                <Typography fontSize={12} fontWeight={700} sx={{display: "-webkit-box", WebkitLineClamp: 4, WebkitBoxOrient: "vertical", overflow: "hidden", overflowWrap: "anywhere"}}>{column.displayName}</Typography>
                                                {column.groupName && <Typography fontSize={10} color="text.secondary" noWrap sx={{maxWidth: "100%"}}>{column.groupName}</Typography>}
                                                {rows.length === 0 && column.sampleValues[0] && <Typography fontSize={11} color="text.secondary" noWrap sx={{maxWidth: "100%"}}>{t("Example")}: {column.sampleValues[0]}</Typography>}
                                            </Button></span></Tooltip>
                                        </TableCell>;
                                    })}
                                </TableRow>
                            </TableHead>
                            <TableBody>{rows.map(row => <TableRow key={row.sourceRowNumber}>
                                <TableCell component="th" scope="row" sx={rowNumberSx}>{row.sourceRowNumber}</TableCell>
                                {visibleColumns.map(column => <TableCell key={column.sourceKey} sx={{width: 210, minWidth: 210, maxWidth: 210, p: 1.5,
                                    bgcolor: roleFor(column) ? "action.selected" : "background.paper", borderRight: "1px solid", borderRightColor: "divider", verticalAlign: "top"}}>
                                    <Tooltip title={row.fieldValues[column.sourceKey] ?? ""}><Typography fontSize={12} sx={{display: "-webkit-box", WebkitLineClamp: 3, WebkitBoxOrient: "vertical", overflow: "hidden", overflowWrap: "anywhere"}}>{row.fieldValues[column.sourceKey] || "—"}</Typography></Tooltip>
                                </TableCell>)}
                            </TableRow>)}</TableBody>
                        </Table>
                        {visibleColumns.length === 0 && <Typography sx={{p: 3}} color="text.secondary">{t("No column matches your search")}</Typography>}
                    </TableContainer>
                    <Box sx={{px: 2, py: 1.25, bgcolor: "background.paper", borderTop: "1px solid", borderTopColor: "divider", display: "flex", alignItems: "center", gap: 1}}>
                        <TableChartOutlinedIcon fontSize="small" color="primary"/><Typography fontSize={12} color="text.secondary">{rows.length > 0 ? t("First {count} product rows from the file", {count: rows.length}) : t("Preview unavailable. Update the API to view original rows.")}</Typography>
                    </Box>
                </Box>
            </Box>
        </DialogContent>
        <DialogActions sx={{px: 3, py: 2, borderTop: "1px solid", borderTopColor: "divider", gap: 1, flexWrap: "wrap"}}>
            <Typography variant="body2" color={canContinue ? "text.secondary" : "warning.main"} sx={{mr: "auto", flexBasis: {xs: "100%", sm: "auto"}}}>
                {analysis.detectedProductRowCount === 0 ? "Не найдено товаров с корректным GTIN. Проверьте файл или выберите другой." : canContinue ? t("Selected characteristics: {count}", {count: selectedCount}) : t("Select a category and product name column.")}
            </Typography>
            <Button variant="outlined" disabled={busy || !canContinue} onClick={() => onSave(normalizedMapping())}>{t("Save selection")}</Button>
            <Button variant="contained" disabled={busy || !canContinue} onClick={() => onContinue(normalizedMapping())}
                endIcon={busy ? <CircularProgress size={16} color="inherit"/> : <ArrowForwardOutlinedIcon/>}>{busy ? t("Preparing preview...") : t("Check products")}</Button>
        </DialogActions>
    </Dialog>;
};

export default ProductFileColumnDialog;
